/* js/data/banks.js — banques de questions (BANKS) : informatique (TES) et Avid Attic (Montage) */

const BANKS={"tes":[{"id":"info","i":"💻","n":"Quiz Informatique","d":"Composants PC, bits, débits et vidéo","levels":[{"n":"Niveau 1","q":[{"q":"Que signifie CPU dans le contexte d’un ordinateur ?","o":["Carte de Processeur Unique","Le « cerveau » de l’ordinateur, qui exécute les calculs","Une carte physique universelle","Un connecteur périphérique USB","Un circuit de puissance utilisateur"],"c":1,"e":"Le CPU (Central Processing Unit) exécute les instructions des programmes et effectue tous les calculs : c’est bien le « cerveau » de la machine.","s":"Composants PC"},{"q":"Quel est le rôle principal du processeur (CPU) ?","o":["Stocker les fichiers de façon permanente","Afficher les images à l’écran","Exécuter les calculs et instructions des programmes","Alimenter le PC en électricité","Connecter le PC à Internet"],"c":2,"e":"Le processeur exécute les calculs et les instructions demandées par les programmes ; les autres tâches reviennent à d’autres composants.","s":"Composants PC"},{"q":"Qu’est-ce que le « socket » sur une carte mère ?","o":["Un port USB supplémentaire","L’emplacement où vient se fixer le processeur","Un type de mémoire vive","Un connecteur pour écran","Le boîtier du disque dur"],"c":1,"e":"Le socket est l’emplacement de la carte mère où se fixe physiquement le processeur ; sa forme doit correspondre au type de CPU.","s":"Composants PC"},{"q":"Que faut-il vérifier avant de choisir un processeur pour une carte mère ?","o":["La couleur du boîtier","La compatibilité du socket","Le nombre de ports USB","La marque de la carte graphique","La capacité du disque dur"],"c":1,"e":"Un processeur ne peut être installé que si son socket correspond à celui de la carte mère : c’est le premier critère de compatibilité.","s":"Composants PC"},{"q":"Quel composant est décrit comme « le circuit central qui relie tous les composants entre eux » ?","o":["Le processeur","La RAM","La carte mère","Le disque SSD","La carte graphique"],"c":2,"e":"La carte mère est le circuit central qui relie CPU, RAM, stockage et cartes d’extension, et permet leur communication.","s":"Composants PC"},{"q":"Que se passe-t-il si la carte mère est défaillante, selon la fiche ?","o":["Seul le son ne fonctionne plus","Rien ne peut communiquer entre les composants","Le disque dur devient plus rapide","Le Wi-Fi cesse de fonctionner","Le processeur chauffe davantage"],"c":1,"e":"Sans carte mère fonctionnelle, plus aucun composant ne peut communiquer entre eux : le PC ne peut pas démarrer.","s":"Composants PC"},{"q":"Quelle est la fonction principale de la carte graphique (GPU) ?","o":["Stocker les fichiers de façon permanente","Calculer et afficher les images, la vidéo et les jeux","Gérer la connexion réseau","Fournir la mémoire vive","Refroidir le processeur"],"c":1,"e":"Le GPU (carte graphique) est spécialisé dans le calcul et l’affichage des images, de la vidéo et des jeux.","s":"Composants PC"},{"q":"Pour quel usage la carte graphique est-elle indispensable, selon la fiche ?","o":["Le stockage longue durée","Un rendu fluide et de bonne qualité","La connexion Wi-Fi","Le son du PC","La communication réseau"],"c":1,"e":"Pour un rendu fluide et de bonne qualité, notamment en jeu vidéo, une carte graphique performante est indispensable.","s":"Composants PC"},{"q":"Quel composant transforme les données numériques en signal audio ?","o":["La carte graphique","La carte son","La RAM","Le SSD","La carte réseau"],"c":1,"e":"La carte son convertit les données numériques du PC en signal audio envoyé aux haut-parleurs ou au casque.","s":"Composants PC"},{"q":"Où la carte son est-elle souvent intégrée ?","o":["Dans le disque dur","Dans la carte graphique","Dans la carte mère","Dans le processeur","Dans le socket"],"c":2,"e":"Sur la plupart des PC, la carte son n’est pas un composant séparé : elle est intégrée directement à la carte mère.","s":"Composants PC"},{"q":"Que signifie RAM ?","o":["Un disque de stockage permanent","Une mémoire rapide et temporaire","Une carte réseau","Un type de processeur","Un port de connexion vidéo"],"c":1,"e":"RAM signifie Random Access Memory : une mémoire rapide mais temporaire, qui stocke les données utilisées activement par les programmes.","s":"Composants PC"},{"q":"Que se passe-t-il avec les données stockées dans la RAM à l’extinction du PC ?","o":["Elles sont gravées définitivement","Elles sont transférées automatiquement sur le SSD","Elles s’effacent","Elles sont envoyées sur le réseau","Elles sont compressées"],"c":2,"e":"La RAM est une mémoire volatile : toutes les données qu’elle contient s’effacent dès que le PC est éteint.","s":"Composants PC"},{"q":"Quel type de stockage utilise un disque mécanique tournant ?","o":["Le SSD","La RAM","Le disque dur (HDD)","La carte mère","Le socket"],"c":2,"e":"Le disque dur (HDD) stocke les données sur un disque magnétique mécanique qui tourne, lu par une tête de lecture.","s":"Composants PC"},{"q":"Quel est l’avantage principal du HDD par rapport au SSD selon la fiche ?","o":["Il est plus rapide","Il est plus silencieux","Il a une grande capacité et un prix bas","Il consomme moins d’électricité","Il n’a pas besoin d’alimentation"],"c":2,"e":"Le principal atout du HDD face au SSD est sa grande capacité de stockage pour un prix nettement plus bas.","s":"Composants PC"},{"q":"Sur quoi repose le stockage d’un disque SSD ?","o":["Un disque mécanique tournant","Des puces électroniques, sans pièces mobiles","Une bande magnétique","Un cristal optique","Une carte perforée"],"c":1,"e":"Le SSD stocke les données sur des puces de mémoire électronique, sans aucune pièce mécanique en mouvement.","s":"Composants PC"},{"q":"Comparé au HDD, le SSD est décrit comme :","o":["Plus lent et plus bruyant","Plus rapide et plus silencieux","Moins cher mais plus lent","Identique en vitesse","Non compatible avec les PC modernes"],"c":1,"e":"Sans pièces mobiles, le SSD est nettement plus rapide et totalement silencieux comparé au HDD.","s":"Composants PC"},{"q":"Par quel type de câble la carte réseau (Ethernet) relie-t-elle le PC au routeur ?","o":["HDMI","USB","RJ45","DisplayPort","Jack audio"],"c":2,"e":"La carte réseau filaire relie le PC au routeur via un câble RJ45, le connecteur standard des réseaux Ethernet.","s":"Composants PC"},{"q":"Quel avantage la connexion Ethernet offre-t-elle selon la fiche ?","o":["Elle est sans fil et pratique","Elle est stable et rapide","Elle ne nécessite aucun câble","Elle fonctionne uniquement avec le Wi-Fi","Elle remplace la carte graphique"],"c":1,"e":"La connexion Ethernet filaire offre une liaison stable et rapide, sans les aléas des ondes radio.","s":"Composants PC"},{"q":"Comment la carte Wi-Fi connecte-t-elle le PC au routeur ?","o":["Par câble RJ45","Par câble USB","Par ondes radio, sans câble","Par fibre optique","Par le port HDMI"],"c":2,"e":"La carte Wi-Fi communique avec le routeur par ondes radio, sans aucun câble physique.","s":"Composants PC"},{"q":"Comparée à l’Ethernet, la connexion Wi-Fi est généralement :","o":["Plus stable et plus rapide","Un peu moins stable et moins rapide, mais plus pratique","Identique en performance","Impossible à utiliser sur un PC fixe","Réservée aux imprimantes"],"c":1,"e":"Le Wi-Fi est généralement un peu moins stable et moins rapide que l’Ethernet, mais bien plus pratique au quotidien.","s":"Composants PC"},{"q":"Quel est le premier élément dans le trajet de l’information au démarrage d’un PC ?","o":["La carte mère","Le processeur","L’alimentation","L’écran","La RAM"],"c":2,"e":"Au démarrage, l’alimentation est le tout premier élément sollicité : elle fournit l’électricité à tous les composants.","s":"Composants PC"},{"q":"Après l’alimentation, quel composant distribue le courant et les données ?","o":["Le SSD","La carte mère","La carte graphique","La RAM","Le Wi-Fi"],"c":1,"e":"Une fois alimentée, c’est la carte mère qui distribue le courant et fait circuler les données vers chaque composant.","s":"Composants PC"},{"q":"Dans le schéma du trajet de l’information, avec quel composant le processeur communique-t-il directement pour les données « sur l’instant » ?","o":["Le disque dur","La carte réseau","La RAM","La carte son","L’écran"],"c":2,"e":"Le processeur échange en permanence des données « à chaud » avec la RAM, la mémoire de travail la plus proche de lui.","s":"Composants PC"},{"q":"Quels composants interviennent juste après le duo Processeur/RAM dans le schéma ?","o":["L’alimentation et la carte mère","Le SSD/HDD et la carte graphique","La carte Wi-Fi et la carte son","Le socket et l’écran","La carte réseau uniquement"],"c":1,"e":"Après le duo Processeur/RAM, l’information transite vers le stockage (SSD/HDD) puis vers la carte graphique pour l’affichage.","s":"Composants PC"},{"q":"Quel est le dernier élément du trajet de l’information selon le schéma ?","o":["La RAM","L’écran","Le SSD","La carte mère","L’alimentation"],"c":1,"e":"L’écran est la dernière étape du trajet de l’information : c’est là que l’image calculée par le GPU est affichée.","s":"Composants PC"},{"q":"Dans l’analogie du bureau utilisée dans la fiche, à quoi correspond le processeur ?","o":["L’armoire d’archives","Le bâtiment","L’employé qui réfléchit et calcule","L’artiste qui dessine","Le bureau de travail"],"c":2,"e":"Dans l’analogie du bureau, le processeur est l’employé qui réfléchit, calcule et exécute le travail.","s":"Composants PC"},{"q":"Dans cette même analogie, à quoi correspond la RAM ?","o":["L’employé","Le bureau de travail avec les dossiers « sous la main »","L’armoire d’archives","Le bâtiment","L’artiste"],"c":1,"e":"La RAM correspond au bureau de travail où l’on garde sous la main les dossiers en cours d’utilisation.","s":"Composants PC"},{"q":"Toujours dans l’analogie, à quoi correspond le disque SSD/HDD ?","o":["L’employé qui calcule","Le bâtiment qui relie les bureaux","L’armoire d’archives où tout est rangé durablement","L’artiste qui dessine","Le bureau de travail temporaire"],"c":2,"e":"Le SSD/HDD est comparé à l’armoire d’archives : l’endroit où tout est rangé durablement, même bureau fermé.","s":"Composants PC"},{"q":"Dans l’analogie, à quoi correspond la carte mère ?","o":["L’artiste qui dessine","Le bâtiment qui relie tous les bureaux entre eux","L’armoire d’archives","Le bureau de travail","L’employé"],"c":1,"e":"La carte mère est le bâtiment qui relie tous les bureaux (composants) entre eux et permet la communication.","s":"Composants PC"},{"q":"Enfin, à quoi correspond la carte graphique dans l’analogie ?","o":["L’employé qui réfléchit","L’artiste qui dessine ce qu’on voit à l’écran","Le bâtiment","L’armoire d’archives","Le bureau de travail"],"c":1,"e":"La carte graphique est comparée à l’artiste qui dessine ce que l’on voit finalement à l’écran.","s":"Composants PC"},{"q":"Le stockage « court terme » évoqué dans la fiche correspond à :","o":["Le SSD","Le disque dur","La RAM","La carte réseau","La carte mère"],"c":2,"e":"Le stockage « court terme » désigne la RAM, rapide mais effacée à l’extinction du PC.","s":"Composants PC"},{"q":"Le stockage « long terme » évoqué dans la fiche correspond à :","o":["La RAM","Le SSD/HDD","Le processeur","La carte son","L’alimentation"],"c":1,"e":"Le stockage « long terme » désigne le SSD/HDD, qui conserve les données même une fois le PC éteint.","s":"Composants PC"},{"q":"Quel élément permet de relier le PC à Internet ou à d’autres appareils ?","o":["La carte son","La carte réseau","Le socket","La RAM","Le disque dur"],"c":1,"e":"La carte réseau (filaire ou Wi-Fi) est le composant qui relie le PC à Internet ou aux autres appareils.","s":"Composants PC"},{"q":"Quel composant est qualifié de « cerveau » de l’ordinateur ?","o":["La carte mère","Le processeur (CPU)","La RAM","Le disque SSD","La carte graphique"],"c":1,"e":"Le processeur (CPU) est le composant qualifié de « cerveau » de l’ordinateur, car il exécute tous les calculs.","s":"Composants PC"},{"q":"Que se passe-t-il si un socket ne correspond pas au modèle de CPU choisi ?","o":["Le PC fonctionne normalement","Le processeur ne peut pas être installé","Seule la RAM est affectée","Le disque dur devient incompatible","Le Wi-Fi cesse de fonctionner"],"c":1,"e":"Si le socket du CPU ne correspond pas à celui de la carte mère, le processeur ne peut tout simplement pas être installé.","s":"Composants PC"},{"q":"Parmi les deux types de stockage interne, lequel n’a aucune pièce mobile ?","o":["Le disque dur (HDD)","Le disque SSD","La RAM","La carte mère","Le socket"],"c":1,"e":"Parmi HDD et SSD, seul le SSD n’a aucune pièce mobile : il repose uniquement sur des puces électroniques.","s":"Composants PC"},{"q":"Quel composant « exécute tous les calculs et instructions des programmes » ?","o":["La carte réseau","Le processeur","La carte son","Le disque dur","La carte Wi-Fi"],"c":1,"e":"Le processeur est le composant qui exécute tous les calculs et toutes les instructions des programmes.","s":"Composants PC"},{"q":"Quelle affirmation est correcte concernant la RAM ?","o":["Elle stocke les données de façon permanente","Elle est rapide et temporaire","Elle remplace le disque dur","Elle sert à afficher les images","Elle gère la connexion réseau"],"c":1,"e":"La RAM est bien rapide et temporaire : elle accélère les traitements en cours mais ne conserve rien après extinction.","s":"Composants PC"},{"q":"Quel élément de la configuration gère le son du PC ?","o":["Le GPU","La carte son","La RAM","Le socket","La carte réseau"],"c":1,"e":"C’est la carte son qui gère la production du son du PC, souvent intégrée à la carte mère.","s":"Composants PC"},{"q":"Quelle carte est « indispensable pour un rendu fluide et de bonne qualité » en jeu vidéo ?","o":["La carte réseau","La carte graphique","La carte son","La carte Wi-Fi","La carte mère"],"c":1,"e":"La carte graphique est indispensable pour obtenir un rendu fluide et de bonne qualité, en particulier dans les jeux vidéo.","s":"Composants PC"},{"q":"Quel est le point commun entre le SSD et le HDD ?","o":["Ce sont tous deux des types de mémoire vive","Ce sont tous deux des solutions de stockage interne","Ce sont tous deux des cartes réseau","Ce sont tous deux des processeurs","Ils remplacent la carte mère"],"c":1,"e":"SSD et HDD sont tous deux des solutions de stockage interne, destinées à conserver les données durablement.","s":"Composants PC"},{"q":"Quelle est la principale différence entre HDD et SSD selon la fiche ?","o":["Le HDD est plus rapide que le SSD","Le HDD utilise un disque mécanique, le SSD des puces électroniques","Le SSD est toujours moins cher que le HDD","Le HDD n’a pas de capacité de stockage","Le SSD ne peut pas stocker de photos"],"c":1,"e":"La différence essentielle est mécanique : le HDD utilise un disque qui tourne, le SSD des puces électroniques sans mouvement.","s":"Composants PC"},{"q":"Selon la fiche, quel type de connexion réseau est « idéale pour le téléchargement ou le jeu en ligne » ?","o":["Le Wi-Fi","L’Ethernet filaire","Le Bluetooth","La RAM","Le SSD"],"c":1,"e":"L’Ethernet filaire est idéale pour le téléchargement ou le jeu en ligne grâce à sa stabilité et sa faible latence.","s":"Composants PC"},{"q":"Quel élément fixe physiquement le processeur sur la carte mère ?","o":["La RAM","Le socket","Le SSD","La carte son","La carte réseau"],"c":1,"e":"Le socket est l’élément de la carte mère qui fixe physiquement le processeur en place.","s":"Composants PC"},{"q":"Dans le trajet de l’information, quel duo de composants fonctionne en interaction constante (flèche « ↔ ») ?","o":["Carte mère et alimentation","Processeur et RAM","SSD et carte graphique","Écran et carte réseau","Socket et carte son"],"c":1,"e":"Le processeur et la RAM interagissent en permanence (flèche ↔) car le CPU a besoin d’accéder très vite aux données en mémoire.","s":"Composants PC"},{"q":"Quelle affirmation décrit le mieux le rôle global de la carte mère ?","o":["Elle affiche les images à l’écran","Elle relie tous les composants et permet leur communication","Elle stocke les fichiers de manière permanente","Elle gère uniquement le son","Elle fournit la connexion Wi-Fi"],"c":1,"e":"La carte mère relie tous les composants entre eux et permet leur communication : c’est son rôle central.","s":"Composants PC"},{"q":"Lequel de ces éléments n’apparaît PAS dans le schéma du trajet de l’information (en 7 étapes) ?","o":["Alimentation","Carte mère","Carte son","Écran","SSD/HDD"],"c":2,"e":"La carte son n’apparaît pas dans le schéma en 7 étapes du trajet de l’information, centré sur le chemin principal des données.","s":"Composants PC"},{"q":"Quel terme désigne la connexion sans fil au routeur ?","o":["Ethernet","RJ45","Wi-Fi","SATA","HDMI"],"c":2,"e":"Le Wi-Fi est le terme désignant la connexion sans fil entre le PC et le routeur.","s":"Composants PC"},{"q":"D’après la fiche, quel composant « calcule et affiche les images, la vidéo et les jeux » ?","o":["Le processeur","La carte graphique (GPU)","La carte son","Le SSD","La carte mère"],"c":1,"e":"La carte graphique (GPU) est le composant qui calcule et affiche les images, la vidéo et les jeux.","s":"Composants PC"},{"q":"Quel est le titre général de cette fiche d’information ?","o":["Vidéo : résolutions, formats et cadence","Informatique : bits, débits & connectiques","Les composants d’un PC","Guide du montage vidéo","Comprendre les réseaux domestiques"],"c":2,"e":"Cette fiche d’information porte sur « Les composants d’un PC », leur rôle et leurs interactions.","s":"Composants PC"},{"q":"Que représente un bit en informatique ?","o":["Un groupe de 8 octets","La plus petite unité d’information numérique (0 ou 1)","Une unité de débit réseau uniquement","Un type de connecteur vidéo","Une unité de résolution d’image"],"c":1,"e":"Un bit est la plus petite unité d’information numérique : il ne peut valoir que 0 ou 1.","s":"Bits, débits & vidéo"},{"q":"Combien de valeurs un bit peut-il prendre ?","o":["De 0 à 9","2 (0 ou 1)","8","1024","Une infinité"],"c":1,"e":"Un bit ne peut prendre que 2 valeurs possibles : 0 ou 1.","s":"Bits, débits & vidéo"},{"q":"Qu’est-ce qu’un octet ?","o":["Un groupe de 8 bits","Un groupe de 8 gigabits","Une unité de débit uniquement","La moitié d’un bit","Un type de câble réseau"],"c":0,"e":"Un octet est un groupe de 8 bits, l’unité de base pour mesurer une quantité de données.","s":"Bits, débits & vidéo"},{"q":"À quoi sert principalement l’octet ?","o":["Mesurer la vitesse du processeur","Mesurer une taille de fichier (Ko, Mo, Go, To)","Mesurer la résolution d’un écran","Mesurer la cadence d’une vidéo","Mesurer la tension électrique"],"c":1,"e":"L’octet sert principalement à mesurer la taille d’un fichier, exprimée en Ko, Mo, Go ou To.","s":"Bits, débits & vidéo"},{"q":"Comment se définit le débit selon la fiche ?","o":["La taille totale d’un fichier","La quantité de données transmises par seconde entre deux points","Le nombre de pixels d’une image","La fréquence du processeur","La capacité de stockage d’un disque"],"c":1,"e":"Le débit correspond à la quantité de données transmises par seconde entre deux points.","s":"Bits, débits & vidéo"},{"q":"En quelle unité le débit d’une connexion se mesure-t-il généralement ?","o":["En Ko uniquement","En bit/s, Mbit/s ou Gbit/s","En pixels par seconde","En volts","En hertz uniquement"],"c":1,"e":"Le débit d’une connexion s’exprime généralement en bits par seconde : bit/s, Mbit/s ou Gbit/s.","s":"Bits, débits & vidéo"},{"q":"En quelle unité mesure-t-on plutôt un transfert de fichier ?","o":["En bit/s","En octets/seconde (Mo/s)","En Hz","En pixels","En watts"],"c":1,"e":"Un transfert de fichier se mesure plutôt en octets par seconde (Mo/s), car les fichiers sont exprimés en octets.","s":"Bits, débits & vidéo"},{"q":"Quel débit approximatif est nécessaire pour du streaming vidéo Full HD (1080p) selon la fiche ?","o":["1 à 2 Mbit/s","5 à 8 Mbit/s","25 à 35 Mbit/s","100 Mbit/s","Plusieurs centaines de Mo/s"],"c":1,"e":"Le streaming vidéo en Full HD (1080p) nécessite environ 5 à 8 Mbit/s de débit.","s":"Bits, débits & vidéo"},{"q":"Quel débit approximatif est nécessaire pour du streaming vidéo 4K selon la fiche ?","o":["5 à 8 Mbit/s","10 Mbit/s","25 à 35 Mbit/s","480 Mbit/s","1 Gbit/s"],"c":2,"e":"Le streaming vidéo en 4K demande un débit bien plus élevé, autour de 25 à 35 Mbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel débit peut demander un fichier vidéo « brut » (non compressé) téléchargé en entier ?","o":["Quelques Kbit/s","5 à 8 Mbit/s","Plusieurs centaines de Mo/s","10 Mbit/s","1 Mbit/s"],"c":2,"e":"Un fichier vidéo brut, non compressé, peut nécessiter un débit de plusieurs centaines de Mo/s pour être transféré intégralement.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit de l’USB 2.0 ?","o":["480 Mbit/s","5 Gbit/s","3 Gbit/s","40 Gbit/s","48 Gbit/s"],"c":0,"e":"L’USB 2.0 offre un débit maximal de 480 Mbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit de l’USB 3.0 ?","o":["480 Mbit/s","5 Gbit/s","6 Gbit/s","10 Gbit/s","1 Gbit/s"],"c":1,"e":"L’USB 3.0 atteint un débit maximal de 5 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"De combien l’USB 3.0 est-il plus rapide que l’USB 2.0 selon la fiche ?","o":["x2","x5","x10","x100","x1000"],"c":2,"e":"Avec 5 Gbit/s contre 480 Mbit/s, l’USB 3.0 est environ 10 fois plus rapide que l’USB 2.0.","s":"Bits, débits & vidéo"},{"q":"Quel connecteur USB 3.0 est souvent reconnaissable par sa couleur ?","o":["Rouge","Vert","Bleu","Jaune","Noir"],"c":2,"e":"Les ports et connecteurs USB 3.0 sont souvent identifiables par leur couleur bleue à l’intérieur.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit du SATA II ?","o":["3 Gbit/s (~300 Mo/s)","6 Gbit/s (~600 Mo/s)","480 Mbit/s","1 Gbit/s","16 Go/s"],"c":0,"e":"Le SATA II offre un débit théorique de 3 Gbit/s, soit environ 300 Mo/s.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit du SATA III ?","o":["3 Gbit/s","6 Gbit/s (~600 Mo/s)","480 Mbit/s","40 Gbit/s","100 Mbit/s"],"c":1,"e":"Le SATA III double ce débit, avec environ 6 Gbit/s, soit environ 600 Mo/s.","s":"Bits, débits & vidéo"},{"q":"Pourquoi le SATA II est-il devenu insuffisant selon la fiche ?","o":["Il ne fonctionne plus avec les cartes mères récentes","Il est trop lent pour les SSD récents","Il ne peut relier que les cartes graphiques","Il n’existe plus dans le commerce","Il ne transmet aucune donnée"],"c":1,"e":"Le SATA II est devenu insuffisant car il ne peut plus suivre la vitesse des SSD récents, plus rapides que sa limite théorique.","s":"Bits, débits & vidéo"},{"q":"Quel bus est décrit comme « très rapide et extensible (par lignes ou lanes) » ?","o":["SATA II","USB 2.0","PCI Express","RJ45 Gigabit","DVI"],"c":2,"e":"Le PCI Express est un bus très rapide et extensible, car on peut ajouter des lignes (lanes) pour augmenter le débit.","s":"Bits, débits & vidéo"},{"q":"Le PCI Express est notamment utilisé pour :","o":["Les claviers et souris uniquement","Les cartes graphiques, SSD NVMe, cartes réseau","Les câbles Ethernet uniquement","Les écrans uniquement","L’alimentation électrique du PC"],"c":1,"e":"Le PCI Express est notamment utilisé pour connecter les cartes graphiques, les SSD NVMe et les cartes réseau.","s":"Bits, débits & vidéo"},{"q":"Quel débit peut atteindre le PCI Express selon la fiche ?","o":["~1 à 16+ Go/s","480 Mbit/s","100 Mbit/s","1 Gbit/s","6 Gbit/s"],"c":0,"e":"Selon le nombre de lanes utilisées, le PCI Express peut atteindre environ 1 à plus de 16 Go/s.","s":"Bits, débits & vidéo"},{"q":"Quel débit maximal peut atteindre le HDMI (version 2.1) ?","o":["10 Gbit/s","32 Gbit/s","48 Gbit/s","5 Gbit/s","100 Gbit/s"],"c":2,"e":"La norme HDMI 2.1 peut atteindre un débit maximal de 48 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"Quelle particularité du HDMI est mentionnée dans la fiche ?","o":["Il ne transporte que l’image, pas le son","Il transporte l’image ET le son dans le même câble","Il ne fonctionne qu’avec les téléviseurs","Il alimente électriquement les périphériques","Il remplace la carte réseau"],"c":1,"e":"Une particularité du HDMI est de transporter à la fois l’image et le son dans un seul et même câble.","s":"Bits, débits & vidéo"},{"q":"Quel débit maximal peut atteindre le DisplayPort (1.4) selon la fiche ?","o":["Jusqu’à 32+ Gbit/s","Jusqu’à 48 Gbit/s","480 Mbit/s","6 Gbit/s","10 Gbit/s"],"c":0,"e":"Le DisplayPort 1.4 peut atteindre un débit maximal supérieur à 32 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel avantage du DisplayPort est cité dans la fiche ?","o":["Il permet de chaîner plusieurs écrans","Il transporte uniquement le son","Il n’existe que sur les téléviseurs","Il alimente le PC en électricité","Il remplace le PCI Express"],"c":0,"e":"Le DisplayPort permet de chaîner plusieurs écrans les uns à la suite des autres via une seule sortie.","s":"Bits, débits & vidéo"},{"q":"Quelle est la limite principale du DVI par rapport au HDMI ?","o":["Il ne transporte pas de son","Il ne transporte pas d’image","Il est plus rapide que le HDMI","Il ne fonctionne pas avec les cartes graphiques","Il n’existe plus du tout"],"c":0,"e":"Contrairement au HDMI, le DVI ne transporte pas de son : c’est sa principale limite.","s":"Bits, débits & vidéo"},{"q":"Quel débit approximatif offre le DVI en dual link ?","o":["~7,9 Gbit/s","48 Gbit/s","480 Mbit/s","100 Mbit/s","1 Gbit/s"],"c":0,"e":"Le DVI en mode dual link peut atteindre un débit d’environ 7,9 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel connecteur combine données, vidéo et charge électrique sur un seul câble ?","o":["DVI","HDMI","Thunderbolt","RJ45","SATA"],"c":2,"e":"Le Thunderbolt combine données, vidéo et charge électrique sur un seul câble USB-C.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit du Thunderbolt (TB3/TB4) ?","o":["40 Gbit/s","480 Mbit/s","6 Gbit/s","10 Mbit/s","100 Gbit/s"],"c":0,"e":"Le Thunderbolt (TB3/TB4) offre un débit maximal de 40 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel type de connecteur utilise le Thunderbolt ?","o":["USB-C","RJ45","HDMI","VGA","Jack audio"],"c":0,"e":"Le Thunderbolt utilise le connecteur physique USB-C.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit du RJ45 Ethernet « classique » (première norme filaire) ?","o":["10 Mbit/s","100 Mbit/s","1 Gbit/s","480 Mbit/s","10 Gbit/s"],"c":0,"e":"La première norme Ethernet filaire RJ45 offrait un débit de 10 Mbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit du RJ45 Fast Ethernet ?","o":["10 Mbit/s","100 Mbit/s","1 Gbit/s","5 Gbit/s","40 Gbit/s"],"c":1,"e":"Le Fast Ethernet (RJ45) atteint un débit de 100 Mbit/s.","s":"Bits, débits & vidéo"},{"q":"Quel est le débit du RJ45 Gigabit, standard actuel pour la maison et le bureau ?","o":["100 Mbit/s","1 Gbit/s","10 Gbit/s","480 Mbit/s","48 Gbit/s"],"c":1,"e":"Le RJ45 Gigabit, standard actuel à la maison et au bureau, offre un débit de 1 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"Quelle particularité de la fibre optique est mentionnée ?","o":["Elle transmet l’électricité à haute tension","Elle transmet la lumière, insensible aux interférences","Elle fonctionne uniquement en Wi-Fi","Elle est plus lente que le RJ45 Ethernet classique","Elle nécessite un port USB"],"c":1,"e":"La fibre optique transmet l’information sous forme de lumière, ce qui la rend insensible aux interférences électromagnétiques.","s":"Bits, débits & vidéo"},{"q":"Quel débit peut atteindre la fibre optique selon la fiche ?","o":["1 à 100+ Gbit/s","10 à 100 Mbit/s","480 Mbit/s maximum","6 Gbit/s maximum","40 Gbit/s maximum seulement"],"c":0,"e":"La fibre optique peut atteindre des débits allant de 1 à plus de 100 Gbit/s.","s":"Bits, débits & vidéo"},{"q":"Parmi ces connectiques, laquelle a le débit le plus faible ?","o":["RJ45 Ethernet (10 Mbit/s)","USB 3.0","SATA III","Thunderbolt","Fibre optique"],"c":0,"e":"Parmi ces connectiques, le RJ45 Ethernet classique (10 Mbit/s) a le débit le plus faible.","s":"Bits, débits & vidéo"},{"q":"Quelle résolution correspond au format « 1080i50 » ?","o":["1280 x 720 px","1920 x 1080 px","3840 x 2160 px","720 x 480 px","2560 x 1440 px"],"c":1,"e":"Le format 1080i50 correspond à une résolution de 1920 x 1080 pixels, avec un balayage entrelacé à 50 Hz.","s":"Bits, débits & vidéo"},{"q":"Que signifie le « i » dans 1080i50 ?","o":["Image","Balayage entrelacé","Balayage progressif","Internet","Intensité"],"c":1,"e":"Le « i » de 1080i signifie balayage entrelacé : l’image est affichée en deux passes (lignes paires puis impaires).","s":"Bits, débits & vidéo"},{"q":"À quel standard le format 1080i50 est-il associé ?","o":["Standard TV européenne (PAL)","Standard cinéma américain","Standard japonais uniquement","Norme USB","Norme HDMI"],"c":0,"e":"Le format 1080i50 est associé au standard TV européen (PAL), qui utilise 50 Hz.","s":"Bits, débits & vidéo"},{"q":"Que signifie le « p » dans 1080p25 ?","o":["Balayage entrelacé","Balayage progressif","Pixels par seconde","Puissance","Port"],"c":1,"e":"Le « p » de 1080p signifie balayage progressif : toutes les lignes de l’image sont affichées en une seule passe.","s":"Bits, débits & vidéo"},{"q":"Le format 1080p25 est particulièrement utilisé dans quel domaine ?","o":["Le jeu vidéo uniquement","Le cinéma/tournage européen","Le stockage de fichiers","La téléphonie","Le réseau domestique"],"c":1,"e":"Le format 1080p25 est particulièrement utilisé dans le cinéma et le tournage en Europe, à 25 images par seconde.","s":"Bits, débits & vidéo"},{"q":"Quelle résolution correspond au format 720p ?","o":["1920 x 1080 px","1280 x 720 px","3840 x 2160 px","640 x 480 px","2560 x 1440 px"],"c":1,"e":"Le format 720p correspond à une résolution de 1280 x 720 pixels.","s":"Bits, débits & vidéo"},{"q":"Comparé au Full HD, le 720p offre :","o":["Plus de détails mais des fichiers plus lourds","Moins de détails mais des fichiers plus légers","Exactement la même qualité","Aucun rapport avec la qualité d’image","Une résolution supérieure au 4K"],"c":1,"e":"Comparé au Full HD, le 720p offre moins de détails mais produit des fichiers plus légers.","s":"Bits, débits & vidéo"},{"q":"Quelle résolution correspond au format UHD/4K ?","o":["1920 x 1080","1280 x 720","3840 x 2160","2560 x 1080","4096 x 2160 uniquement"],"c":2,"e":"Le format UHD/4K correspond à une résolution de 3840 x 2160 pixels.","s":"Bits, débits & vidéo"},{"q":"Combien de fois plus de pixels l’UHD/4K contient-il par rapport au Full HD selon la fiche ?","o":["2 fois plus","4 fois plus","8 fois plus","10 fois plus","Autant de pixels"],"c":1,"e":"L’UHD/4K contient environ 4 fois plus de pixels que le Full HD.","s":"Bits, débits & vidéo"},{"q":"Quel format est décrit comme « le plus courant (TV, streaming, jeux) » ?","o":["HD","FHD (Full HD)","UHD/4K","720p uniquement","1080i50 uniquement"],"c":1,"e":"Le Full HD (FHD) est le format le plus courant, utilisé en télévision, streaming et jeux vidéo.","s":"Bits, débits & vidéo"},{"q":"Comment fonctionne le balayage entrelacé selon la fiche ?","o":["Toutes les lignes sont affichées en même temps","Les lignes paires puis impaires sont affichées en alternance","Seules les lignes paires sont affichées","L’image est divisée en quatre quadrants","Il n’y a pas de lignes affichées"],"c":1,"e":"Dans le balayage entrelacé, les lignes paires de l’image sont affichées puis les lignes impaires, en alternance rapide.","s":"Bits, débits & vidéo"},{"q":"Quel est l’avantage du balayage entrelacé mentionné dans la fiche ?","o":["Il offre une meilleure netteté","Il économise de la bande passante","Il élimine le scintillement","Il augmente la résolution","Il double la cadence d’images"],"c":1,"e":"L’avantage du balayage entrelacé est d’économiser de la bande passante en n’envoyant qu’une partie de l’image à chaque passage.","s":"Bits, débits & vidéo"},{"q":"Quel est l’avantage du balayage progressif selon la fiche ?","o":["Il économise davantage de bande passante que l’entrelacé","Il offre une image plus nette, sans scintillement","Il divise la résolution par deux","Il fonctionne uniquement en noir et blanc","Il ne nécessite pas d’écran"],"c":1,"e":"Le balayage progressif offre une image plus nette et sans scintillement, car toutes les lignes sont affichées d’un coup.","s":"Bits, débits & vidéo"},{"q":"Que signifie une cadence de 25 fps ?","o":["25 images complètes affichées chaque seconde","25 pixels par image","25 secondes par image","25 Mbit/s de débit","25 couleurs affichées"],"c":0,"e":"Une cadence de 25 fps signifie que 25 images complètes sont affichées chaque seconde.","s":"Bits, débits & vidéo"},{"q":"Pourquoi la cadence de 50 fps est-elle utilisée pour le sport ou le ralenti selon la fiche ?","o":["Elle réduit la taille du fichier","Elle rend le mouvement beaucoup plus fluide","Elle nécessite moins de bande passante que 25 fps","Elle correspond au standard américain","Elle élimine le besoin de balayage progressif"],"c":1,"e":"Une cadence de 50 fps rend le mouvement beaucoup plus fluide, ce qui est particulièrement apprécié pour le sport ou le ralenti.","s":"Bits, débits & vidéo"}]},{"n":"Niveau 2","q":[{"q":"Que désigne le cache L1 d’un processeur ?","o":["La mémoire vive principale","La plus petite mémoire, la plus rapide, intégrée au cœur du CPU","Le disque dur système","La mémoire de la carte graphique","Le firmware du BIOS"],"c":1,"e":"Le cache L1 est directement intégré au cœur, minuscule mais quasi aussi rapide que les registres du processeur."},{"q":"Pourquoi la mémoire cache est-elle organisée en plusieurs niveaux (L1, L2, L3) ?","o":["Pour compresser les données","Pour équilibrer vitesse (petite mémoire proche du cœur) et capacité (mémoire plus grande mais plus lente)","Pour chiffrer les données du processeur","Pour remplacer la RAM totalement","Pour gérer le refroidissement"],"c":1,"e":"Plus un cache est proche du cœur, plus il est rapide mais petit ; L3, plus loin, est plus grand mais plus lent : c’est un compromis vitesse/capacité."},{"q":"Qu’est-ce que le multiplicateur de fréquence d’un CPU ?","o":["Le nombre de cœurs physiques","Le facteur par lequel la fréquence de bus est multipliée pour obtenir la fréquence du cœur","Le nombre de threads simultanés","La tension d’alimentation du CPU","Le nombre de caches disponibles"],"c":1,"e":"La fréquence finale du CPU = fréquence de bus × multiplicateur ; augmenter l’un ou l’autre change la vitesse d’horloge."},{"q":"Quelle est la différence entre un northbridge et un southbridge sur les anciennes cartes mères ?","o":["Ce sont deux noms pour le même composant","Le northbridge gère les liaisons rapides (RAM, GPU), le southbridge les périphériques plus lents","Le southbridge gère uniquement le refroidissement","Le northbridge est un type de RAM","Le southbridge remplace le CPU"],"c":1,"e":"Le northbridge gérait les liaisons rapides (RAM, GPU), le southbridge les périphériques plus lents (USB, disques) ; ils sont aujourd’hui souvent fusionnés dans le CPU/chipset."},{"q":"Qu’est-ce que la latence CAS (CL) d’une barrette de RAM ?","o":["Sa capacité en Go","Le nombre de cycles d’horloge avant qu’une donnée demandée soit disponible","Sa fréquence en MHz","Le nombre de broches du connecteur","Sa consommation électrique"],"c":1,"e":"Le CAS Latency compte les cycles d’horloge entre la demande d’une donnée et sa disponibilité : plus il est bas, plus la RAM répond vite à fréquence égale."},{"q":"Quelle est la principale différence entre la DDR4 et la DDR5 ?","o":["La DDR5 n’existe que sur portable","La DDR5 offre des fréquences et bandes passantes plus élevées avec une tension réduite","La DDR4 est plus rapide que la DDR5","Elles utilisent le même connecteur physique","La DDR5 ne fonctionne qu’avec l’AMD"],"c":1,"e":"La DDR5 grimpe à des fréquences plus élevées et gère l’alimentation sur le module lui-même, avec une tension réduite pour l’efficacité énergétique."},{"q":"Qu’apporte la mémoire ECC (Error-Correcting Code) ?","o":["Une fréquence plus élevée","La détection et correction automatique des erreurs de bits en mémoire","Un stockage permanent des données","Une compression des données","Un chiffrement matériel"],"c":1,"e":"L’ECC ajoute des bits de contrôle qui permettent de détecter et corriger les erreurs mémoire, crucial pour les serveurs où la fiabilité prime."},{"q":"Quel est l’avantage principal du protocole NVMe par rapport à AHCI/SATA pour un SSD ?","o":["Il est moins cher","Il permet un parallélisme massif des commandes via PCIe, réduisant fortement la latence","Il fonctionne uniquement en USB","Il n’a pas besoin de pilote","Il stocke plus de données par cellule"],"c":1,"e":"Le NVMe communique directement en PCIe avec de multiples files d’attente parallèles, alors qu’AHCI/SATA était conçu à l’origine pour les disques durs mécaniques plus lents."},{"q":"Que signifie IOPS dans le contexte d’un SSD ?","o":["Le débit séquentiel maximal","Le nombre d’opérations d’entrée/sortie par seconde, révélateur des performances en accès aléatoire","La capacité totale du disque","La température maximale supportée","La durée de vie en années"],"c":1,"e":"Les IOPS comptent les opérations par seconde plutôt que le volume de données, ce qui reflète mieux les performances en accès aléatoire (petits fichiers, base de données)."},{"q":"Qu’est-ce que le RAID 1 ?","o":["Une répartition des données sans redondance pour la vitesse","Une duplication (mise en miroir) des données sur deux disques pour la sécurité","Un chiffrement matériel des disques","Une compression automatique des fichiers","Un protocole réseau"],"c":1,"e":"Le RAID 1 écrit la même donnée sur deux disques simultanément : si un disque tombe en panne, l’autre garde une copie intacte."},{"q":"Quelle est la bande passante par lane (voie) du PCI Express 4.0 ?","o":["~1 Go/s par lane","~2 Go/s par lane","~4 Go/s par lane","~8 Go/s par lane","~16 Go/s par lane"],"c":1,"e":"Chaque génération de PCIe double le débit par lane de la précédente ; la 4.0 atteint environ 2 Go/s par lane (16 Go/s en x8)."},{"q":"Que signifie le chroma subsampling 4:2:0 utilisé en vidéo ?","o":["Une réduction de la résolution spatiale de l’image","Une réduction de la résolution de couleur (chrominance) tout en gardant la pleine luminance","Une compression du son uniquement","Un mode d’affichage entrelacé","Un format de fichier audio"],"c":1,"e":"L’œil humain est plus sensible à la luminosité qu’à la couleur : le 4:2:0 réduit donc la résolution de chrominance sans perte visible notable, économisant de la bande passante."},{"q":"Quelle est la différence fondamentale entre HDR10 et le SDR (Standard Dynamic Range) ?","o":["Le HDR10 offre une plage de luminosité et de contraste bien plus étendue","Le HDR10 réduit la résolution de l’image","Le SDR consomme plus de bande passante","Le HDR10 ne fonctionne qu’en noir et blanc","Il n’y a aucune différence perceptible"],"c":0,"e":"Le HDR élargit la plage entre les noirs profonds et les blancs très lumineux, donnant une image avec beaucoup plus de contraste et de nuances que le SDR classique."},{"q":"Qu’est-ce que le DSC (Display Stream Compression) utilisé par le DisplayPort et le HDMI récents ?","o":["Un chiffrement de sécurité pour la vidéo","Une compression visuellement sans perte permettant de transmettre des résolutions/fréquences plus élevées","Un protocole audio surround","Une réduction de la résolution native de l’écran","Un mode d’économie d’énergie"],"c":1,"e":"Le DSC compresse le flux vidéo de façon quasi imperceptible pour l’œil, ce qui permet de faire passer des résolutions/fréquences que le câble ne supporterait pas en brut."},{"q":"Quelle est la principale différence entre les codecs H.264 et H.265 (HEVC) ?","o":["H.265 offre une meilleure compression pour une qualité équivalente, à coût de calcul plus élevé","H.264 est plus récent que H.265","H.265 ne fonctionne qu’en 4K","H.264 ne compresse pas la vidéo","Ils sont strictement identiques"],"c":0,"e":"H.265 utilise des algorithmes plus sophistiqués (blocs de taille variable, meilleure prédiction) pour diviser le poids du fichier à qualité égale, au prix de plus de calcul à l’encodage/décodage."},{"q":"Que permet le Multi-Stream Transport (MST) du DisplayPort ?","o":["Chaîner plusieurs écrans à partir d’une seule sortie vidéo","Doubler la fréquence du processeur","Fusionner plusieurs disques durs","Augmenter la RAM disponible","Réduire la latence du clavier"],"c":0,"e":"Le MST permet à une seule sortie DisplayPort de gérer plusieurs écrans en série, chacun recevant sa portion de bande passante."},{"q":"Qu’est-ce que le VRR (Variable Refresh Rate), comme le FreeSync ou G-Sync ?","o":["Une synchronisation de la fréquence de rafraîchissement de l’écran avec le nombre d’images produites par le GPU","Un mode de veille automatique de l’écran","Une compression audio adaptative","Un protocole de sécurité HDMI","Une technologie de stockage rapide"],"c":0,"e":"Le VRR ajuste la fréquence de rafraîchissement de l’écran image par image pour qu’elle corresponde exactement au nombre d’images produites, éliminant déchirures et saccades."},{"q":"Quelle est la bande passante totale du standard USB4 ?","o":["480 Mbit/s","5 Gbit/s","10 Gbit/s","40 Gbit/s","100 Gbit/s"],"c":3,"e":"L’USB4 reprend l’architecture du Thunderbolt 3 et atteint jusqu’à 40 Gbit/s, loin devant les 10 Gbit/s de l’USB 3.2 Gen 2."},{"q":"Qu’est-ce que le jitter dans une transmission réseau ou vidéo ?","o":["La perte totale du signal","La variation de la latence entre les paquets ou trames reçus","Le débit maximal théorique","La résolution maximale supportée","Un type de compression"],"c":1,"e":"Le jitter, c’est l’irrégularité du délai entre les paquets : même avec un bon débit moyen, un jitter élevé casse la fluidité audio/vidéo en temps réel."},{"q":"Pourquoi la fibre optique monomode a-t-elle une portée bien supérieure à la multimode ?","o":["Elle transporte plus de couleurs","Son cœur plus fin limite la dispersion du signal lumineux sur de longues distances","Elle utilise l’électricité au lieu de la lumière","Elle est toujours plus large que la multimode","Elle ne nécessite pas de connecteur"],"c":1,"e":"Le monomode utilise un cœur très fin qui limite la dispersion modale du signal lumineux, permettant de parcourir des dizaines de kilomètres contre quelques centaines de mètres en multimode."}]},{"n":"Niveau 3","q":[{"q":"Qu’est-ce que l’exécution dans le désordre (out-of-order execution) d’un CPU moderne ?","o":["L’exécution des instructions dans un ordre aléatoire non contrôlé","Une technique où le processeur réordonne dynamiquement les instructions pour éviter d’attendre les dépendances et maximiser les unités d’exécution","Un mode de panne du processeur","Une erreur logicielle à corriger par le BIOS","Un protocole de communication entre cœurs"],"c":1,"e":"Plutôt que d’exécuter les instructions strictement dans l’ordre du programme, le CPU avance sur celles dont les données sont prêtes, puis remet les résultats dans le bon ordre à la fin : cela évite d’attendre inutilement."},{"q":"Que mesure l’IPC (Instructions Per Cycle) d’un processeur ?","o":["Sa fréquence en GHz","Le nombre moyen d’instructions exécutées par cycle d’horloge, reflet de l’efficacité architecturale","Sa consommation électrique en watts","Le nombre de cœurs physiques","La taille du cache L3"],"c":1,"e":"Un IPC élevé signifie que l’architecture accomplit plus de travail utile par cycle, ce qui explique pourquoi deux CPU à la même fréquence peuvent avoir des performances très différentes."},{"q":"Quel est le rôle d’un TLB (Translation Lookaside Buffer) dans un CPU ?","o":["Stocker temporairement les traductions récentes d’adresses virtuelles en adresses physiques pour accélérer la mémoire virtuelle","Traduire les instructions x86 en microcode","Gérer la température du processeur","Stocker les pilotes graphiques","Chiffrer les échanges réseau"],"c":0,"e":"Traduire une adresse virtuelle en adresse physique à chaque accès mémoire serait trop lent : le TLB garde en cache les traductions récentes pour accélérer ce processus."},{"q":"Qu’est-ce que la cohérence de cache (cache coherency) dans un CPU multicœur ?","o":["Le fait que tous les cœurs partagent exactement la même fréquence","Le mécanisme garantissant que tous les cœurs voient une vue cohérente d’une même donnée modifiée en cache","Une technique de compression du cache L3","La synchronisation des ventilateurs du CPU","Le partage de la RAM entre plusieurs PC"],"c":1,"e":"Sans cohérence de cache, un cœur pourrait lire une valeur périmée pendant qu’un autre cœur vient de la modifier dans son propre cache ; le protocole de cohérence synchronise ces copies."},{"q":"Quelle est la différence entre la latence mémoire (en ns) et la bande passante mémoire (en Go/s) ?","o":["Ce sont deux termes identiques pour la même mesure","La latence mesure le délai avant la première donnée, la bande passante mesure le débit une fois le transfert lancé","La latence ne concerne que le SSD, la bande passante que la RAM","La bande passante mesure uniquement la fréquence du CPU","La latence est toujours plus élevée que la bande passante"],"c":1,"e":"La latence est le temps d’attente avant que la première donnée arrive, la bande passante est le débit une fois le flux de données lancé : un système peut avoir une latence faible mais un débit modeste, ou l’inverse."},{"q":"Qu’est-ce que le rank dans une configuration de mémoire DDR (single-rank vs dual-rank) ?","o":["Le nombre de barrettes physiques installées","Un ensemble de puces mémoire sur une barrette agissant comme une unité adressable indépendante, impactant le parallélisme mémoire","La fréquence maximale supportée","La tension nominale du module","La génération de la norme DDR"],"c":1,"e":"Un rank est un groupe de puces qui répond comme une seule unité ; avoir plusieurs ranks permet au contrôleur mémoire d’enchaîner les accès sur des ranks différents sans attendre, améliorant le débit effectif."},{"q":"Pourquoi le NVMe utilise-t-il plusieurs files d’attente (queues) matérielles contrairement à AHCI ?","o":["Pour réduire artificiellement les performances","Pour exploiter le parallélisme du CPU multicœur avec jusqu’à 65 000 files, réduisant la contention et la latence","Pour limiter la capacité de stockage","Parce que le SATA ne permet pas les files d’attente","Pour compresser les données avant écriture"],"c":1,"e":"Avec des dizaines de milliers de files d’attente possibles au lieu d’une seule (AHCI), le NVMe peut exploiter tous les cœurs du CPU pour envoyer des commandes en parallèle sans se bloquer mutuellement."},{"q":"Qu’est-ce que le write amplification sur un SSD ?","o":["Le fait que le volume de données réellement écrit sur la mémoire flash est supérieur au volume logique envoyé, à cause de la gestion des blocs","Une augmentation artificielle de la capacité affichée","Un bug logiciel rare","La compression des données avant écriture","La vitesse de lecture séquentielle"],"c":0,"e":"Les SSD écrivent par blocs entiers : modifier une petite donnée peut obliger à réécrire tout un bloc, donc le volume physique écrit sur la flash dépasse le volume logique demandé, ce qui use la mémoire plus vite."},{"q":"Quelle est la différence entre le PCIe en mode x4 « électrique » et x16 « mécanique » sur un connecteur ?","o":["Il n’y a jamais de différence entre taille physique et nombre de lanes actives","Le connecteur peut être physiquement plus grand (x16) que le nombre de lanes réellement câblées (x4), un choix de conception carte mère","Le mode électrique concerne uniquement l’alimentation du GPU","x4 et x16 désignent toujours la même bande passante","Le mode mécanique ne transmet aucune donnée"],"c":1,"e":"Un connecteur physique x16 peut n’avoir que 4 lanes réellement câblées (x4 électrique) pour réduire les coûts de la carte mère, tout en acceptant physiquement une carte plus large."},{"q":"Qu’est-ce que le DisplayPort Alt Mode sur un port USB-C ?","o":["Un mode qui transmet un signal DisplayPort natif directement sur les broches USB-C, sans conversion de protocole","Un adaptateur logiciel qui convertit l’USB en HDMI","Un mode réservé au chargement rapide uniquement","Une fonction qui désactive le port USB","Un protocole propriétaire incompatible avec DisplayPort"],"c":0,"e":"Le signal DisplayPort est envoyé tel quel sur certaines broches du connecteur USB-C, sans passer par une puce de conversion de protocole, ce qui minimise la latence et la complexité."},{"q":"Quelle est la différence entre la compression vidéo intra-image et inter-image (prédiction temporelle) ?","o":["L’intra-image compresse chaque image indépendamment, l’inter-image exploite les similarités entre images successives (I/P/B-frames)","L’inter-image ne fonctionne qu’en noir et blanc","L’intra-image est toujours plus efficace que l’inter-image","Ce sont deux noms pour la même technique","L’inter-image ne s’applique qu’au son"],"c":0,"e":"L’intra-image compresse chaque image comme une photo isolée (comme un JPEG), tandis que l’inter-image ne stocke que les différences par rapport aux images voisines, ce qui réduit énormément la taille du fichier vidéo."},{"q":"Qu’apporte l’AV1 par rapport au H.265/HEVC en matière de codec vidéo ?","o":["Un codec libre de droits offrant une compression généralement supérieure, au prix d’un encodage plus coûteux en calcul","Un format exclusivement destiné à l’audio","Une compatibilité uniquement avec les anciens téléviseurs","Une résolution maximale limitée au 720p","Un débit fixe non compressible"],"c":0,"e":"L’AV1 est développé par un consortium ouvert (pas de royalties) et utilise des techniques de compression plus avancées que le HEVC, au prix d’un temps d’encodage nettement plus long."},{"q":"Que signifie la profondeur de couleur 10 bits par canal (10-bit) par rapport au 8 bits ?","o":["Une résolution d’image plus élevée","Un nombre de nuances de couleur par canal bien supérieur (1024 contre 256), réduisant le banding visible en HDR","Une fréquence d’images plus élevée","Un débit audio plus élevé","Une compression sans perte garantie"],"c":1,"e":"Avec 8 bits, chaque canal de couleur n’a que 256 nuances possibles, ce qui peut créer des bandes visibles dans les dégradés ; le 10 bits offre 1024 nuances par canal, bien plus fluide, surtout important en HDR."},{"q":"Qu’est-ce que la latence d’affichage (input lag) totale d’un écran inclut-elle typiquement ?","o":["Uniquement le temps de réponse du panneau (pixel response time)","Le traitement du signal par l’électronique de l’écran additionné au temps de réponse du panneau","Uniquement la fréquence de rafraîchissement","Le débit du câble utilisé, rien d’autre","La résolution native de l’écran"],"c":1,"e":"L’écran reçoit le signal, le traite (mise à l’échelle, HDR, etc.) puis l’affiche : ce traitement électronique s’ajoute au temps de réponse physique des pixels pour former le délai total perçu."},{"q":"Pourquoi le Thunderbolt peut-il transporter à la fois PCIe, DisplayPort et USB sur un même câble ?","o":["Parce qu’il tunnelise plusieurs protocoles sur une couche de transport commune à haut débit","Parce qu’il utilise trois câbles physiques distincts en un seul connecteur","Parce qu’il convertit tout en signal analogique","Parce qu’il n’est en réalité que de l’USB renommé","Parce qu’il n’existe qu’une seule norme sans tunnelisation"],"c":0,"e":"Le Thunderbolt établit un tunnel de données générique à très haut débit sur lequel plusieurs protocoles (PCIe, DisplayPort, USB) circulent simultanément, chacun étant encapsulé puis extrait à l’autre bout."},{"q":"Quelle est la différence entre le débit théorique et le débit réel (goodput) d’une liaison réseau ?","o":["Ce sont des synonymes stricts","Le débit théorique est la capacité maximale de la norme, le débit réel tient compte des surcoûts protocolaires, collisions et conditions réelles","Le débit réel est toujours supérieur au débit théorique","Le débit théorique ne concerne que la fibre optique","Le débit réel ne dépend que du câble utilisé"],"c":1,"e":"Les en-têtes de protocole, les retransmissions et les conditions réelles du réseau consomment une partie de la capacité théorique : le débit réellement utile (goodput) est donc toujours inférieur à la norme affichée."},{"q":"Qu’est-ce que le MIMO (Multiple Input, Multiple Output) en Wi-Fi ?","o":["L’utilisation de plusieurs antennes en émission et réception pour transmettre plusieurs flux de données simultanément et améliorer débit/portée","Un mode d’économie d’énergie du routeur","Un protocole de chiffrement Wi-Fi","Une limitation du nombre d’appareils connectés","Un type de câble Ethernet"],"c":0,"e":"En multipliant les antennes, le MIMO envoie plusieurs flux de données sur le même canal en même temps, ce qui augmente le débit total sans avoir besoin de plus de fréquence."},{"q":"Que signifie l’OFDM (Orthogonal Frequency-Division Multiplexing) utilisé en Wi-Fi et en 4G/5G ?","o":["Une technique divisant un canal en nombreuses sous-porteuses orthogonales pour transmettre des données en parallèle et résister aux interférences","Un protocole de sécurité biométrique","Une norme de câblage RJ45","Un format de compression audio","Un mode d’affichage vidéo entrelacé"],"c":0,"e":"En répartissant les données sur de nombreuses sous-porteuses étroites et orthogonales, l’OFDM résiste mieux aux interférences et permet une utilisation plus efficace du spectre disponible."},{"q":"Pourquoi la latence est-elle un facteur plus critique que le débit pour le cloud gaming ou les appels vidéo en temps réel ?","o":["Parce qu’un débit élevé suffit toujours à masquer la latence","Parce que même avec un débit élevé, un délai de transmission trop long rend l’interaction perceptiblement décalée et inutilisable en temps réel","Parce que la latence n’affecte que le stockage local","Parce que le débit et la latence sont mathématiquement identiques","Parce que la latence ne concerne que les réseaux filaires"],"c":1,"e":"Même à très haut débit, chaque paquet met un temps incompressible à faire l’aller-retour ; en temps réel (voix, jeu), c’est ce délai — pas le volume de données — qui rend l’expérience saccadée ou fluide."}]}]}],"mon":[{"id":"attic","i":"🗂️","n":"Quiz Avid Attic","d":"Media Composer : retrouver ses sauvegardes de bins","levels":[{"n":"Quiz","q":[{"s":"Emplacement","q":"Sous Windows, où se trouve le dossier Avid Attic ?","o":["C:/Program Files/Avid/Attic","drive:/Users/Public/Public Documents/Avid editing application","drive:/Users/Nom/Documents/Avid Projects","drive:/Windows/Temp/Avid"],"c":1,"e":"Sous Windows, l’Attic se trouve dans Users/Public/Public Documents/Avid editing application."},{"s":"Emplacement","q":"Sous Mac, quel est le chemin du dossier Avid Attic ?","o":["Macintosh HD/Applications/Avid Attic","Macintosh HD/Users/Shared/Avid editing application/Avid Attic","Macintosh HD/Bibliothèque/Avid/Attic","Macintosh HD/Users/Bureau/Attic"],"c":1,"e":"Sur Mac : Macintosh HD/Users/Shared/Avid editing application/Avid Attic."},{"s":"Procédure","q":"Quelle est la toute première étape pour récupérer un fichier depuis l’Attic ?","o":["Fermer définitivement le projet","Supprimer le bin actuel","Redémarrer l’ordinateur","Réduire (minimiser) l’application Avid"],"c":3,"e":"On commence par minimiser l’application Avid, puis on ouvre le dossier Avid Attic depuis le bureau."},{"s":"Structure","q":"À l’ouverture du dossier Avid Attic, que voit-on ?","o":["Un dossier pour chaque projet","Un dossier pour chaque média importé","Un seul fichier de sauvegarde global","Un dossier pour chaque date"],"c":0,"e":"L’Attic affiche un dossier par projet."},{"s":"Structure","q":"Une fois dans le dossier d’un projet, quel dossier faut-il ouvrir pour trouver les sauvegardes de bins ?","o":["Sequences","Bins","Media Files","Settings"],"c":1,"e":"On ouvre le dossier du projet, puis le dossier Bins, qui contient un dossier par bin du projet."},{"s":"Sauvegardes","q":"Comment est nommé un fichier de sauvegarde d’un bin appelé « Source Clips » ?","o":["Source Clips.1, Source Clips.2…","Backup_Source Clips","Source Clips_copie","SourceClips.bak"],"c":0,"e":"Un fichier de sauvegarde porte le même nom que le bin, avec un numéro ajouté (Source Clips.1, Source Clips.2…)."},{"s":"Sauvegardes","q":"Comment afficher les dates de création des fichiers de sauvegarde dans le dossier d’un bin ?","o":["Clic droit > Propriétés","View > Details","Edit > Sort","Fichier > Historique"],"c":1,"e":"Si le dossier n’est pas déjà en mode Détails, on choisit View > Details pour voir les dates de création."},{"s":"Récupération","q":"Que fait Ctrl+glisser un fichier de sauvegarde vers le bureau ?","o":["Il déplace le fichier et vide l’Attic","Il supprime le fichier de l’Attic","Il copie le fichier et laisse l’original dans l’Attic","Il ouvre directement le bin dans Avid"],"c":2,"e":"Ctrl+glisser fait une copie : les fichiers originaux restent dans l’Attic."},{"s":"Récupération","q":"Vers quel emplacement copie-t-on les fichiers de sauvegarde dans la procédure ?","o":["La corbeille","Le dossier des médias","Le bureau","Le dossier Projet Avid"],"c":2,"e":"On copie les bins de sauvegarde sur le bureau, puis on les ouvre depuis Avid."},{"s":"Réouverture","q":"Dans la fenêtre Projet, quel onglet faut-il activer pour ouvrir un bin de sauvegarde ?","o":["Settings","Usage","Bins","Format"],"c":2,"e":"On clique sur la fenêtre Projet, puis sur l’onglet Bins, avant de choisir File > Open Bin."},{"s":"Réouverture","q":"Dans la boîte de dialogue d’ouverture, quel type de fichier faut-il sélectionner (Files of Type) ?","o":["Avid Bins (*.avb)","All Files (*.*)","Sequences only","Media (*.mxf)"],"c":1,"e":"Les fichiers de sauvegarde ont un numéro ajouté à leur nom : il faut choisir All Files (*.*) pour les voir."},{"s":"Réouverture","q":"Quand on ouvre un bin de sauvegarde, où Avid crée-t-il un lien vers ce bin ?","o":["Dans le dossier Attic","Dans le dossier Other Bins","Dans le dossier Trash","Dans la timeline"],"c":1,"e":"Un lien vers le bin de sauvegarde situé sur le bureau est créé dans le dossier Other Bins."},{"s":"Règle d’or","q":"Peut-on ouvrir en même temps un bin et sa copie de sauvegarde ?","o":["Oui, sans limite","Oui, mais seulement sur Mac","Non : il faut garder les autres bins fermés et ouvrir les sauvegardes une par une","Oui, si le bin est vide"],"c":2,"e":"Avid n’autorise pas l’ouverture simultanée d’un bin et de sa copie."},{"s":"Récupération","q":"Une fois le bin de sauvegarde ouvert, que faire pour conserver son contenu ?","o":["L’enregistrer sous le même nom que l’original","Créer un nouveau bin (ex. « Audio New ») et y glisser le contenu voulu","Copier-coller tout le dossier Attic","Renommer le projet"],"c":1,"e":"On crée un nouveau bin (par exemple Audio New pour Audio.2) et on y glisse le matériel à garder."},{"s":"Nettoyage","q":"Que fait-on à la fin, une fois le contenu récupéré ?","o":["On laisse tout tel quel","On supprime les bins de sauvegarde dans Other Bins, puis on jette les fichiers du bureau à la corbeille","On vide tout le dossier Attic","On réinstalle Avid"],"c":1,"e":"On sélectionne et supprime les bins de sauvegarde dans Other Bins, puis on glisse les fichiers du bureau à la corbeille."}]}]}]};
